import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第三册：培养技能 · Lesson 41 Illusions of pastoral peace","description":"学习 while 与 whereas 的对照，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 41 Illusions of pastoral peace","description":"学习 while 与 whereas 的对照，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 while 与 whereas 的对照，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 40 Who's who","link":"/life/english/new-concept/book-3/unit-02/lesson-040"},"next":{"text":"第三册：培养技能 · Lesson 42 Modern cavemen","link":"/life/english/new-concept/book-3/unit-03/lesson-042"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 40 Who's who","link":"/life/english/new-concept/book-3/unit-02/lesson-040"},"next":{"text":"第三册：培养技能 · Lesson 42 Modern cavemen","link":"/life/english/new-concept/book-3/unit-03/lesson-042"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-041.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-041.md"}`),i={name:"life/english/new-concept/book-3/unit-03/lesson-041.md"};function s(l,e,r,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-41-illusions-of-pastoral-peace" tabindex="-1">第三册：培养技能 · Lesson 41 Illusions of pastoral peace <a class="header-anchor" href="#第三册-培养技能-·-lesson-41-illusions-of-pastoral-peace" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 41 Illusions of pastoral peace&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从对乡村安宁的想象与实际体验之间的差距，训练对比论述。比较城乡生活时需分别说明噪声来源、活动时间和个人需求，不用一句“更好”覆盖所有维度。学习 while 和 whereas 表达对照，同时识别 while 的时间意义，避免误判句间关系。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>pastoral</td><td>/ˈpɑːstərəl/</td><td>adj.</td><td>田园的</td><td>a pastoral scene</td></tr><tr><td>illusion</td><td>/ɪˈluːʒən/</td><td>n.</td><td>错觉</td><td>an illusion of peace</td></tr><tr><td>disturbance</td><td>/dɪˈstɜːbəns/</td><td>n.</td><td>干扰</td><td>a sudden disturbance</td></tr><tr><td>convenience</td><td>/kənˈviːniəns/</td><td>n.</td><td>便利</td><td>urban convenience</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in contrast — 相比之下，引出差异</li><li>far from — 远非，也可表示距离很远</li></ul><h2 id="语法讲解-while-与-whereas-的对照" tabindex="-1">语法讲解：while 与 whereas 的对照 <a class="header-anchor" href="#语法讲解-while-与-whereas-的对照" aria-label="Permalink to &quot;语法讲解：while 与 whereas 的对照&quot;">​</a></h2><p>while 可表示“当……时”的同时背景，也可表示两种事实的对比，具体意义取决于分句是否构成并列差异。whereas 明确表示对照，通常不表示时间。两者都可连接完整分句，主语不必相同。对照不自动等于逻辑矛盾，例如一个地方清静而交通不便是两个维度，而不是互相否定。写比较段落时尽量让两侧使用相同评价标准和相近结构，读者才能看出差别；若需要表达承认条件但仍得出结论，应考虑 although 的让步关系。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The village is quiet after sunset, whereas the market town remains busy until midnight.</p></blockquote><p>村庄日落后很安静，而集镇一直忙碌到午夜。</p><p>whereas 对照两个地方在夜间的活动状态，不表示一个事件发生在另一个事件期间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>while 不能每次都译作“当……时”；While Anna likes silence, Ben enjoys company 中表达的是偏好对照。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 whereas 两侧时保持平衡语调，分别重读 close 和 long；回听能否辨认作者最终偏好及理由。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The city flat is close to work, whereas the cottage requires a long drive. The cottage offers more outdoor space. For now, a shorter commute matters more to me.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>比较两种居住环境，用三句写出同一维度的差异与个人取舍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先比较通勤，再补充空间，最后说明个人权重而非普遍优劣。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句比较的是交通还是夜间活动？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 夜间活动。</p><p><strong>解析：</strong> quiet after sunset 与 busy until midnight 是对应信息。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填入明确表示对照的连接词：I work indoors, ___ she works outside.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whereas</p><p><strong>解析：</strong> whereas 明确引出对照。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>while 在 While I cooked, he washed the dishes 中主要表示什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 时间上的同时。</p><p><strong>解析：</strong> 两个动作可以同时发生。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：while 与 whereas 的对照。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-040">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-042">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
